// Public Service Announcement lessons 6–10: filming, audio and editing, copyright and credits,
// airing and measuring impact with the upload, and the Round Two presentation.
const RULES=['HOSA Public Service Announcement 2026–27 guidelines and rating sheets','https://hosa.org/wp-content/uploads/2026/10/PSA-26-27-10.6.pdf'];
const HFC=['Hilarity for Charity','https://www.wearehfc.org'];
const COPY=['U.S. Copyright Office: What is copyright?','https://www.copyright.gov/what-is-copyright/'];
const FAIR=['U.S. Copyright Office: Fair use index','https://www.copyright.gov/fair-use/'];
const CC=['Creative Commons: About CC licenses','https://creativecommons.org/share-your-work/cclicenses/'];
const EVAL=['CDC: Framework for program evaluation','https://www.cdc.gov/evaluation/php/evaluation-framework/index.html'];
const UPLOAD=['HOSA: Competitive event digital uploads','https://hosa.org/competitive-event-digital-uploads/'];
const COMM=['CDC: Health communication','https://www.cdc.gov/health-communication/php/index.html'];
const q=(p,a,b,c,d,e)=>[p,[a,b,c,d],e];
const match=(title,pairs)=>({t:'w',kind:'match',title,pairs});
const order=(title,steps)=>({t:'w',kind:'order',title,steps});
const sort=(title,buckets,items)=>({t:'w',kind:'sort',title,buckets,items});
const flip=(title,cards)=>({t:'w',kind:'flip',title,cards});
const kase=(title,nodes)=>({t:'w',kind:'case',title,start:'a',nodes});
const chk=(q,options,why)=>({t:'check',q,options,why});
